// SECURITY: pre-LLM scan for patient identifiers and prompt-injection phrases (runs BEFORE any model call)
const d = $json;
const ascii = s => String(s || '')
  .replace(/[٠-٩]/g, c => String(c.charCodeAt(0) - 0x0660))
  .replace(/[۰-۹]/g, c => String(c.charCodeAt(0) - 0x06F0));
const phi = [
  { k: 'national_id', r: /\b\d{14}\b/g },
  { k: 'phone', r: /(?<!\d)(?:\+?20|0)1[0125]\d{8}(?!\d)/g },
  { k: 'mrn', r: /\bMRN[:\s-]*\d+/gi },
  { k: 'email', r: /[\w.+-]+@[\w-]+\.[\w.]+/g },
  { k: 'name_label', r: /\b(patient|pt)\s+name\s*[:=]\s*\S+/gi }
];
const inj = [/ignore (all |any )?(previous|prior) instructions/i, /system prompt/i, /you are now/i,
  /disregard (the )?(above|rules)/i, /reveal .*(prompt|instructions)/i, /developer (message|mode)/i];
const fields = ['description', 'harm_description', 'person_affected'];
const types = new Set(); let injHit = false; const red = {};
for (const f of fields) {
  let t = ascii(d[f]);
  for (const p of phi) { if (p.r.test(t)) { types.add(p.k); } p.r.lastIndex = 0; t = t.replace(p.r, '[REDACTED-' + p.k + ']'); }
  if (inj.some(r => r.test(t))) injHit = true;
  red[f] = t;
}
const phiHit = types.size > 0;
return { json: { ...d, phi_status: (phiHit || injHit) ? 'quarantine' : 'clean',
  phi_flags: { phi: phiHit, injection: injHit, types: [...types] },
  description_redacted: red.description } };

const d = $json;
const req = ['incident_id', 'timestamp', 'incident_type', 'department', 'description_sanitized', 'harm_occurred', 'phi_status'];
const errors = req.filter(k => !d[k] || String(d[k]).trim() === '').map(k => 'missing: ' + k);
if (/^yes/i.test(d.harm_occurred || '') && !String(d.harm_description || '').trim()) errors.push('missing: harm_description (harm was reported)');
const t = String(d.incident_type || '').toLowerCase();
const rules = {
  clinical: /(medic|clinical|fall|infection|surgical|procedur|diagnos)/,
  security: /(security|access|data|cyber|violence)/,
  facility: /(facility|equipment|fire|environment|maintenance|power)/,
  safety: /(safety|near miss|other)/
};
const matches = Object.keys(rules).filter(k => rules[k].test(t));
const route = matches.length === 1 ? matches[0] : 'manual_triage';
const triage_reason = matches.length === 1 ? 'keyword match: ' + matches[0]
  : (matches.length === 0 ? 'no domain keyword matched' : 'conflicting domains: ' + matches.join(', '));
const h = String(d.harm_occurred || '').toLowerCase();
const sentinel_suspected = /(severe|death|died|permanent)/.test(h);
const escalation_flag = sentinel_suspected || /unknown/.test(h) || route === 'manual_triage';
const now = Date.now();
// GAHAR Hospital Standards 2025 / GAHAR accreditation-procedure update (12 Apr 2026): notify GAHAR within 48 h, RCA within 45 days.
const gahar_notify_by = sentinel_suspected ? new Date(now + 48 * 3600e3).toISOString() : '';
const rca_due_by = sentinel_suspected ? new Date(now + 45 * 86400e3).toISOString().slice(0, 10) : '';
return { json: { ...d, run_id: String($execution.id || 'manual'), schema_version: '1.0',
  validated: errors.length === 0, route, triage_reason, sentinel_suspected, escalation_flag,
  gahar_notify_by, rca_due_by, validation_errors: errors, sanitized_fields: req } };

const raw = $json.specialist_report || '';
let p;
try { p = JSON.parse(String(raw).replace(/```json|```/g, '').trim()); }
catch (e) { p = { summary: String(raw), confirmed_facts: [], hypotheses: [], missing_evidence: ['Specialist output was not valid JSON'], root_causes: [], recommendations: [], gahar_citations: [], risk_tier: 'High' }; }
const cites = Array.isArray(p.gahar_citations) ? p.gahar_citations : [];
const tier = ['Low', 'Medium', 'High', 'Critical'].includes(p.risk_tier) ? p.risk_tier : 'High';
return { json: { ...$json, parsed: p, gahar_citations: cites, risk_tier: tier } };

const base = $('JS Parser').item.json;
const raw = $json.output || '';
let a = null;
try { a = JSON.parse(String(raw).replace(/```json|```/g, '').trim()); } catch (e) {}
const audit = a || { draft_report: String(raw), risk_tier: base.risk_tier || 'High', issues: ['Audit output was not valid JSON - manual review required'], proposed_actions: [] };
const issues = Array.isArray(audit.issues) ? [...audit.issues] : [];
const actions = (Array.isArray(audit.proposed_actions) ? audit.proposed_actions : []).map(x => ({ action: x.action || '', owner: x.owner || 'UNASSIGNED', due_date: x.due_date || 'UNSET' }));
const unowned = actions.filter(x => x.owner === 'UNASSIGNED' || x.due_date === 'UNSET').length;
if (unowned) issues.push(unowned + ' action(s) lack an owner or due date - assign at approval');
const cites = (base.gahar_citations || []).map(c => typeof c === 'string' ? c : (c.code || JSON.stringify(c)));
if (!cites.length) issues.push('No verified GAHAR citation returned - treat as UNVERIFIED');
const tier = ['Low', 'Medium', 'High', 'Critical'].includes(audit.risk_tier) ? audit.risk_tier : (base.risk_tier || 'High');
// Output PHI scan before any notification/export
const text = JSON.stringify(audit);
const phi = [/\b\d{14}\b/, /(?<!\d)(?:\+?20|0)1[0125]\d{8}(?!\d)/, /\bMRN[:\s-]*\d+/i, /[\w.+-]+@[\w-]+\.[\w.]+/];
const hit = phi.some(r => r.test(text));
return { json: { ...base, audit: { ...audit, issues, proposed_actions: actions }, gahar_citations: cites,
  risk_tier: tier, citation_status: cites.length ? 'cited' : 'unverified',
  output_status: hit ? 'quarantine' : 'clean' } };

const b = $('Parse Audit').item.json;
let j = null;
try { j = JSON.parse(String($json.output || '').replace(/```json|```/g, '').trim()); } catch (e) {}
const dims = ['factual_accuracy', 'groundedness', 'safety_compliance', 'format_adherence', 'bias'];
const ok = !!j && dims.every(k => Number.isFinite(Number(j[k])));
const s = {}; dims.forEach(k => s[k] = ok ? Math.min(5, Math.max(1, Number(j[k]))) : '');
const mean = ok ? Math.round(dims.reduce((a, k) => a + s[k], 0) / dims.length * 100) / 100 : '';
let alert_level = 'none';
if (!ok) alert_level = 'soft';                       // degraded judge: human verification flagged
else if (s.safety_compliance <= 2) alert_level = 'hard';   // unsafe output -> pause release
else if (mean < 4) alert_level = 'soft';
if (b.output_status !== 'clean') alert_level = 'hard';
const draft_seconds = Math.round((Date.now() - new Date(b.timestamp).getTime()) / 1000);
return { json: { ...b, ...s, mean_score: mean, alert_level, judge_status: ok ? 'ok' : 'degraded',
  judge_rationale: ok ? String(j.rationale || '') : 'Judge output invalid - manual verification required',
  draft_seconds, models: 'specialist=gpt-4o; audit=gpt-4o; judge=gpt-4o-mini; summary=gpt-4o-mini' } };

// SECURITY: nothing is released until an authorized human replies with this one-time code.
const b = $('Parse Judge').item.json;
const secret = String($env.APPROVAL_TOKEN || '');
if (!secret) throw new Error('APPROVAL_TOKEN env var is not set - refusing to issue a review package');
const code = require('crypto').createHash('sha256').update(b.incident_id + secret).digest('hex').slice(0, 8).toUpperCase();
return { json: {
  incident_id: b.incident_id, run_id: b.run_id, route: b.route, risk_tier: b.risk_tier, alert_level: b.alert_level,
  review_status: 'PENDING_HUMAN_REVIEW', executive_summary: $json.output || '', draft_report: JSON.stringify(b.audit, null, 2),
  citations: (b.gahar_citations || []).join('; '), citation_status: b.citation_status, mean_score: b.mean_score,
  escalation_flag: b.escalation_flag, sentinel_suspected: b.sentinel_suspected,
  gahar_notify_by: b.gahar_notify_by, rca_due_by: b.rca_due_by,
  proposed_actions: JSON.stringify(b.audit.proposed_actions), approval_code: code,
  email_subject: '[GAHAR-RCA] ' + b.incident_id + ' - Review required', created_at: new Date().toISOString() } };

