// SECURITY: parse a decision from the authorized mailbox OR the signed webhook. Fail closed.
const item = $json;
const secret = String($env.APPROVAL_TOKEN || '');
const allow = String($env.AUTHORIZED_APPROVERS || '').toLowerCase().split(',').map(s => s.trim()).filter(Boolean);
const mail = r => { const s = typeof r === 'object' && r ? (r.text || (r.value && r.value[0] && r.value[0].address) || '') : String(r || ''); const m = s.match(/[\w.+-]+@[\w-]+\.[\w.]+/); return m ? m[0].toLowerCase() : ''; };
const isHook = !!(item.body && (item.body.incident_id || item.body.approval_decision));
let channel, id = '', decision = '', reviewer = '', owner = '', due = '', comment = '', codeIn = '', tokenOk = true;
if (isHook) {
  const b = item.body; channel = 'webhook';
  id = String(b.incident_id || ''); decision = String(b.approval_decision || '').toLowerCase().replace(/_/g, ' ');
  reviewer = mail(b.reviewer_email); owner = String(b.action_owner || ''); due = String(b.due_date || ''); comment = String(b.comment || ''); codeIn = String(b.approval_code || '');
  tokenOk = !!secret && String((item.headers || {})['x-approval-token'] || '') === secret;
} else {
  channel = 'email';
  const subj = String(item.subject || '');
  const text = String(item.textPlain || item.text || '').split('\n').filter(l => !l.trim().startsWith('>')).join('\n');
  const idm = subj.match(/INC-[A-Z0-9-]+/i); id = idm ? idm[0].toUpperCase() : '';
  const first = (text.split('\n').map(l => l.trim()).find(l => l) || '').toLowerCase();
  const dm = first.match(/^(approved|rejected|request edits)/); decision = dm ? dm[1] : '';
  reviewer = mail(item.from);
  const g = re => { const m = text.match(re); return m ? m[1].trim() : ''; };
  codeIn = g(/CODE:\s*([A-Za-z0-9]{8})/i); owner = g(/OWNER:\s*(.+)/i); due = g(/DUE:\s*(\d{4}-\d{2}-\d{2})/i); comment = g(/COMMENT:\s*(.+)/i);
}
let expected = '';
if (secret && id) expected = require('crypto').createHash('sha256').update(id + secret).digest('hex').slice(0, 8).toUpperCase();
const reasons = [];
if (!secret) reasons.push('APPROVAL_TOKEN not configured');
if (!id) reasons.push('no incident id');
if (!['approved', 'rejected', 'request edits'].includes(decision)) reasons.push('no valid decision');
if (!allow.includes(reviewer)) reasons.push('sender not in authorized list');
if (!tokenOk) reasons.push('bad webhook token');
if (!expected || codeIn.toUpperCase() !== expected) reasons.push('one-time code mismatch');
return { json: { incident_id: id, approval_decision: decision, reviewer_id: reviewer, action_owner: owner, due_date: due,
  reviewer_comment: comment, approval_channel: channel, authorized: reasons.length === 0, reject_reason: reasons.join('; '),
  received_at: new Date().toISOString() } };

const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const q = $('Dashboard Webhook').item.json.query || {};
const tok = String($env.DASHBOARD_TOKEN || '');
if (!tok || q.token !== tok) return { json: { status: 401, html: '<h1>401 Unauthorized</h1>' } };
const rows = n => { try { return $(n).all().map(i => i.json).filter(r => r && Object.keys(r).length); } catch (e) { return []; } };
const J = rows('Read Judge Scores'), A = rows('Read Action Register'), F = rows('Read Failed Runs');
const num = v => Number(v); const ok = v => v !== '' && v != null && Number.isFinite(num(v));
const avg = k => { const v = J.map(r => r[k]).filter(ok).map(num); return v.length ? (v.reduce((a, b) => a + b, 0) / v.length).toFixed(2) : 'n/a'; };
const med = a => { if (!a.length) return null; const s = [...a].sort((x, y) => x - y); const m = Math.floor(s.length / 2); return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2; };
const dm = med(J.map(r => r.draft_seconds).filter(ok).map(num));
const today = new Date().toISOString().slice(0, 10);
const overdue = A.filter(r => r.review_status === 'APPROVED' && r.due_date && String(r.due_date) < today && String(r.action_status || '').toUpperCase() !== 'DONE').length;
const esc_n = A.filter(r => String(r.escalation_flag) === 'true').length;
const pending = A.filter(r => r.review_status === 'PENDING_HUMAN_REVIEW').length;
const soft = J.filter(r => r.alert_level === 'soft').length, hard = J.filter(r => r.alert_level === 'hard').length;
const failRate = (J.length + F.length) ? (100 * F.length / (J.length + F.length)).toFixed(1) + '%' : 'n/a';
const kpi = (l, v, t) => '<div class="k"><div class="v">' + esc(v) + '</div><div class="l">' + esc(l) + '</div><div class="t">' + esc(t) + '</div></div>';
const html = '<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Incident AI Dashboard</title><style>body{font-family:system-ui,sans-serif;margin:24px;background:#f6f7f9;color:#1b1f24}h1{font-size:20px}.g{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:12px}.k{background:#fff;border-radius:10px;padding:14px;box-shadow:0 1px 3px #0002}.v{font-size:28px;font-weight:600}.l{font-size:13px}.t{font-size:11px;color:#667}table{border-collapse:collapse;background:#fff;margin-top:16px}td,th{padding:6px 12px;border-bottom:1px solid #e3e5e8;font-size:13px;text-align:left}</style><h1>Hospital Incident AI - monitoring (synthetic data)</h1><div class="g">'
  + kpi('Median draft time (min)', dm == null ? 'n/a' : (dm / 60).toFixed(1), 'target <= 10 (baseline 20 assumed, unverified)')
  + kpi('Incidents processed', J.length, 'judge-scored drafts')
  + kpi('Awaiting human review', pending, 'no release without authorized approval')
  + kpi('Escalations', esc_n, 'sentinel / unknown harm / manual triage')
  + kpi('Overdue actions', overdue, 'approved, past due, not DONE')
  + kpi('Failed-run rate', failRate, 'soft alert > 5%')
  + kpi('Soft / hard alerts', soft + ' / ' + hard, 'soft: mean < 4.0; hard: unsafe output')
  + '</div><table><tr><th>Judge dimension</th><th>Mean (1-5)</th></tr>'
  + ['factual_accuracy', 'groundedness', 'safety_compliance', 'format_adherence', 'bias', 'mean_score'].map(k => '<tr><td>' + k + '</td><td>' + avg(k) + '</td></tr>').join('')
  + '</table><p class="t">Routing accuracy requires the gold-labeled benchmark run and is not computed here. Generated ' + esc(new Date().toISOString()) + '.</p>';
return { json: { status: 200, html } };
